import fs from "fs";
import path from "path";
import { Post, SiteConfig } from "./types";

function escapeXml(str: string): string {
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

export function generateRssFeed(posts: Post[], config: SiteConfig): string {
  const items = posts
    .filter((p) => !p.frontmatter.draft)
    .map((p) => {
      const date = p.frontmatter.date || new Date().toISOString();
      const url = new URL(p.url, config.baseUrl).href;
      return `    <item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid isPermaLink="true">${escapeXml(url)}</guid>
      <pubDate>${new Date(date).toUTCString()}</pubDate>
      <description>${escapeXml(p.html.substring(0, 500))}</description>
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.title)}</title>
    <description>${escapeXml(config.description)}</description>
    <link>${escapeXml(config.baseUrl)}</link>
    <atom:link href="${escapeXml(new URL("/rss.xml", config.baseUrl).href)}" rel="self" type="application/rss+xml"/>
    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>
${items}
  </channel>
</rss>`;
}

export function writeRssFeed(outputDir: string, posts: Post[], config: SiteConfig): void {
  const rss = generateRssFeed(posts, config);
  const rssPath = path.join(outputDir, "rss.xml");
  fs.mkdirSync(path.dirname(rssPath), { recursive: true });
  fs.writeFileSync(rssPath, rss, "utf-8");
}

import fs from "fs";
import path from "path";
import { Post, SiteConfig } from "./types";
import { TemplateContext, renderPage } from "./renderer";
import Handlebars from "handlebars";

export function buildTagIndex(
  posts: Post[]
): { tags: Record<string, Post[]>; tagList: Array<{ name: string; count: number }> } {
  const tags: Record<string, Post[]> = {};

  for (const post of posts) {
    if (post.frontmatter.draft) continue;
    for (const tag of post.frontmatter.tags) {
      if (!tags[tag]) tags[tag] = [];
      tags[tag].push(post);
    }
  }

  const tagList = Object.entries(tags)
    .map(([name, tagPosts]) => ({ name, count: tagPosts.length }))
    .sort((a, b) => b.count - a.count);

  return { tags, tagList };
}

export function generateTagPages(
  tags: Record<string, Post[]>,
  tagList: Array<{ name: string; count: number }>,
  templates: Record<string, Handlebars.TemplateDelegate>,
  layouts: Record<string, Handlebars.TemplateDelegate>,
  outputDir: string,
  allPosts: Post[],
  config: SiteConfig
): void {
  const tagDir = path.join(outputDir, "tags");
  fs.mkdirSync(tagDir, { recursive: true });

  for (const [tag, tagPosts] of Object.entries(tags)) {
    const context: TemplateContext = {
      content: "",
      title: `Posts tagged "${tag}"`,
      tags: [tag],
      url: `/tags/${encodeURIComponent(tag)}.html`,
      site: {
        ...config,
        posts: tagPosts,
        tags: tagList,
      },
    };

    let html: string;
    if (templates.tag) {
      html = renderPage("tag", templates, layouts, context);
    } else if (templates.index) {
      html = renderPage("index", templates, layouts, context);
    } else {
      html = buildDefaultTagPage(tag, tagPosts, config);
    }

    const filePath = path.join(tagDir, `${encodeURIComponent(tag)}.html`);
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, html, "utf-8");
  }
}

function buildDefaultTagPage(tag: string, posts: Post[], config: SiteConfig): string {
  const items = posts
    .map(
      (p) =>
        `<li><a href="${p.url}">${p.frontmatter.title}</a>${p.frontmatter.date ? ` — ${p.frontmatter.date}` : ""}</li>`
    )
    .join("\n");

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Posts tagged "${tag}" — ${config.title}</title>
</head>
<body>
  <h1>Posts tagged "${tag}"</h1>
  <ul>${items}</ul>
  <p><a href="/">← Back to home</a></p>
</body>
</html>`;
}

import fs from "fs";
import path from "path";
import { Post, SiteConfig } from "./types";
import { loadPosts } from "./frontmatter";
import { markdownToHtml } from "./markdown";
import { loadTemplates, renderPage, TemplateContext } from "./renderer";
import { writeRssFeed } from "./rss";
import { buildTagIndex, generateTagPages } from "./tags";
import { CopyOptions } from "fs";

export function generateSite(
  sourceDir: string,
  templateDir: string,
  outputDir: string,
  config: SiteConfig
): void {
  const posts = loadPosts(sourceDir);

  const { templates, layouts } = loadTemplates(templateDir);

  for (const post of posts) {
    post.html = markdownToHtml(post.content);
  }

  fs.mkdirSync(outputDir, { recursive: true });

  for (const post of posts) {
    const context: TemplateContext = {
      content: post.html,
      title: post.frontmatter.title,
      date: post.frontmatter.date,
      tags: post.frontmatter.tags,
      url: post.url,
      site: {
        ...config,
        posts,
        tags: [],
      },
    };

    let html: string;
    try {
      html = renderPage("post", templates, layouts, context);
    } catch {
      html = renderPage("page", templates, layouts, context);
    }

    const outPath = path.join(outputDir, post.slug + ".html");
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, html, "utf-8");
  }

  const publishedPosts = posts.filter((p) => !p.frontmatter.draft);
  const { tags, tagList } = buildTagIndex(publishedPosts);

  const indexContext: TemplateContext = {
    content: "",
    title: config.title,
    tags: [],
    url: "/",
    site: {
      ...config,
      posts: publishedPosts,
      tags: tagList,
    },
  };

  let indexHtml: string;
  if (templates.index) {
    indexHtml = renderPage("index", templates, layouts, indexContext);
  } else {
    indexHtml = buildDefaultIndex(config.title, publishedPosts);
  }
  fs.writeFileSync(path.join(outputDir, "index.html"), indexHtml, "utf-8");

  generateTagPages(tags, tagList, templates, layouts, outputDir, publishedPosts, config);

  writeRssFeed(outputDir, publishedPosts, config);

  copyStatic(templateDir, outputDir);
}

function buildDefaultIndex(title: string, posts: Post[]): string {
  const items = posts
    .map(
      (p) =>
        `<li><a href="${p.url}">${p.frontmatter.title}</a>${p.frontmatter.date ? ` — ${p.frontmatter.date}` : ""}</li>`
    )
    .join("\n");

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${title}</title>
</head>
<body>
  <h1>${title}</h1>
  <ul>${items}</ul>
</body>
</html>`;
}

function copyStatic(templateDir: string, outputDir: string): void {
  const staticDir = path.join(templateDir, "static");
  if (!fs.existsSync(staticDir)) return;
  copyDirSync(staticDir, outputDir);
}

function copyDirSync(src: string, dest: string): void {
  fs.mkdirSync(dest, { recursive: true });
  const entries = fs.readdirSync(src, { withFileTypes: true });
  for (const entry of entries) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyDirSync(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

import http from "http";
import fs from "fs";
import path from "path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import { generateSite } from "./generator";
import { SiteConfig } from "./types";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__livereload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') {
      ws.close();
      location.reload();
    }
  };
  ws.onclose = function() {
    setTimeout(function() {
      var retry = new WebSocket('ws://' + location.host + '/__livereload');
      retry.onmessage = function(msg) {
        if (msg.data === 'reload') location.reload();
      };
    }, 1000);
  };
})();
</script>
`;

export function startDevServer(
  sourceDir: string,
  templateDir: string,
  outputDir: string,
  port: number,
  config: SiteConfig
): void {
  console.log(`Building site...`);
  generateSite(sourceDir, templateDir, outputDir, config);

  const server = http.createServer((req, res) => {
    const url = req.url || "/";
    const urlPath = url === "/" ? "/index.html" : url;

    const filePath = path.join(outputDir, urlPath);
    const ext = path.extname(filePath).toLowerCase();

    const mimeTypes: Record<string, string> = {
      ".html": "text/html",
      ".css": "text/css",
      ".js": "application/javascript",
      ".json": "application/json",
      ".png": "image/png",
      ".jpg": "image/jpeg",
      ".svg": "image/svg+xml",
      ".xml": "application/xml",
      ".ico": "image/x-icon",
    };

    const contentType = mimeTypes[ext] || "application/octet-stream";

    try {
      let content = fs.readFileSync(filePath);
      if (contentType === "text/html") {
        let html = content.toString("utf-8");
        html = html.replace("</body>", RELOAD_SCRIPT + "</body>");
        content = Buffer.from(html, "utf-8");
      }
      res.writeHead(200, { "Content-Type": contentType });
      res.end(content);
    } catch {
      res.writeHead(404, { "Content-Type": "text/plain" });
      res.end("Not Found");
    }
  });

  const wss = new WebSocketServer({ server });

  const watcher = chokidar.watch([sourceDir, templateDir], {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 100, pollInterval: 50 },
  });

  const rebuild = () => {
    try {
      console.log("Change detected, rebuilding...");
      generateSite(sourceDir, templateDir, outputDir, config);
      console.log("Site rebuilt. Reloading browsers...");
      wss.clients.forEach((client) => {
        if (client.readyState === WebSocket.OPEN) {
          client.send("reload");
        }
      });
    } catch (err) {
      console.error("Build error:", err);
    }
  };

  let rebuildTimeout: NodeJS.Timeout | null = null;
  watcher.on("change", () => {
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(rebuild, 300);
  });
  watcher.on("add", () => {
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(rebuild, 300);
  });
  watcher.on("unlink", () => {
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(rebuild, 300);
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}/`);
  });
}

#!/usr/bin/env node

import { resolve } from "path";
import { generateSite } from "./generator";
import { startDevServer } from "./server";
import { SiteConfig } from "./types";

function showHelp(): void {
  console.log(`
Static Site Generator (ssg)

Usage: ssg [options]

Options:
  --source, -s       Source directory of Markdown files        [required]
  --templates, -t    Template directory of Handlebars files     [required]
  --output, -o       Output directory for generated site        [required]
  --serve            Start dev server with live reload
  --port, -p         Port for dev server          [default: 3000]
  --title            Site title                    [default: "My Site"]
  --description      Site description              [default: ""]
  --base-url         Base URL for RSS feed        [default: "http://localhost:3000"]
  --help, -h         Show this help

Examples:
  ssg --source content --templates theme --output public
  ssg -s content -t theme -o public --serve --port 8080
  ssg -s src -t tpl -o dist --title "My Blog" --base-url "https://example.com"
  `);
}

function parseArgs(args: string[]): Record<string, string> {
  const result: Record<string, string> = {};
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === "--help" || arg === "-h") {
      result.help = "true";
      continue;
    }
    if (arg === "--serve") {
      result.serve = "true";
      continue;
    }
    const next = args[i + 1];
    if (next === undefined || next.startsWith("-")) continue;

    switch (arg) {
      case "--source":
      case "-s":
        result.source = next;
        i++;
        break;
      case "--templates":
      case "-t":
        result.templates = next;
        i++;
        break;
      case "--output":
      case "-o":
        result.output = next;
        i++;
        break;
      case "--port":
      case "-p":
        result.port = next;
        i++;
        break;
      case "--title":
        result.title = next;
        i++;
        break;
      case "--description":
        result.description = next;
        i++;
        break;
      case "--base-url":
        result["base-url"] = next;
        i++;
        break;
    }
  }
  return result;
}

function main(): void {
  const args = parseArgs(process.argv.slice(2));

  if (args.help) {
    showHelp();
    return;
  }

  if (!args.source || !args.templates || !args.output) {
    console.error("Error: --source, --templates, and --output are required.");
    console.error("Use --help for usage information.");
    process.exit(1);
  }

  const sourceDir = resolve(args.source);
  const templateDir = resolve(args.templates);
  const outputDir = resolve(args.output);
  const port = parseInt(args.port || "3000", 10);

  const config: SiteConfig = {
    title: args.title || "My Site",
    description: args.description || "",
    baseUrl: args["base-url"] || `http://localhost:${port}`,
  };

  if (args.serve === "true") {
    startDevServer(sourceDir, templateDir, outputDir, port, config);
  } else {
    console.log(`Building site from ${sourceDir} to ${outputDir}...`);
    generateSite(sourceDir, templateDir, outputDir, config);
    console.log("Site built successfully.");
  }
}

main();
